import { Router } from "express";
import type { Env } from "../config/env.js";

const CONFIG_VERSION = 1;

export function createConfigRouter(env: Env): Router {
  const router = Router();

  const payload = {
    fingerprintSalt: env.fingerprintSalt,
    fingerprintFields: env.fingerprintFields,
    siteDomain: env.siteDomain,
    configVersion: CONFIG_VERSION,
  };

  router.get("/api/config.json", (_req, res) => {
    // no-cache + ETag (generated by Express): clients revalidate every time but
    // get a cheap 304 when nothing changed, so bank/salt/locale edits propagate
    // on the next request instead of being pinned for a day by `immutable`.
    res.set("Cache-Control", "no-cache");
    res.json(payload);
  });

  return router;
}
